<section class="panel registration-section"><div class="section-heading"><h2>หน้าที่ของฉัน</h2></div><div class="section-body">
<?php if(!$myDuties): ?><p class="muted">ยังไม่มีหน้าที่ที่ได้รับมอบหมาย</p><?php endif ?>
<?php foreach($myDuties as $duty): ?><article class="duty-card"><strong><?= e(duty_types()[$duty['type']]) ?> · <?= e($duty['group_name']??$duty['team_name']??($duty['field_name']?:'งานทั่วไป')) ?></strong><p><?= e($duty['description']) ?></p><a class="text-link" href="<?= e(url($duty['type']==='field'?'scoring':'duties',['camp_id'=>$duty['camp_id']])) ?>"><?= e($duty['camp_name']) ?> →</a></article><?php endforeach ?>
</div></section>
<section class="panel registration-section"><div class="section-heading"><h2>งาน Timeline ของฉัน</h2></div><div class="section-body"><?php if(!$myTasks): ?><p class="muted">ยังไม่มีงานที่ได้รับมอบหมาย</p><?php endif ?><?php foreach($myTasks as $task): ?><article class="duty-card"><span class="badge <?= $task['status']==='done'?'active':'draft' ?>"><?= e(task_statuses()[$task['status']]) ?></span><strong> <?= e($task['name']) ?></strong><p><?= e($task['camp_name']) ?> · <?= e($task['task_date']) ?> <?= e(substr($task['task_time'],0,5)) ?></p><form method="post" action="<?= e(url('timeline',['camp_id'=>$task['camp_id']])) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= e($task['id']) ?>"><input type="hidden" name="version" value="<?= e($task['version']) ?>"><button class="button secondary" name="status" value="<?= $task['status']==='done'?'not_done':'done' ?>"><?= $task['status']==='done'?'เปลี่ยนเป็นยังไม่เสร็จ':'ทำเสร็จแล้ว' ?></button></form></article><?php endforeach ?></div></section>
